changeSet.sql:
DO $$
DECLARE
    v_count integer;
BEGIN
    ALTER TABLE nexus.tuples NO FORCE ROW LEVEL SECURITY;
    SELECT count(*) INTO v_count FROM nexus.tuples WHERE octet_length(body) > 4096;
    ALTER TABLE nexus.tuples FORCE ROW LEVEL SECURITY;
    RAISE NOTICE 'tuples-003-1: % legacy row(s) found in nexus.tuples with body > 4096 UTF-8 bytes; tuples-003-2 deletes them next', v_count;
END $$;

ALTER TABLE nexus.tuples NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuple_claim_log NO FORCE ROW LEVEL SECURITY;
DELETE FROM nexus.tuples WHERE octet_length(body) > 4096;
ALTER TABLE nexus.tuple_claim_log FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuples FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.tuples
    ADD CONSTRAINT chk_tuples_body_size
    CHECK (octet_length(body) <= 4096) NOT VALID;
